<?php declare(strict_types=1); namespace Annam; $title='WhatsApp connection';$subtitle='Connect your WhatsApp number and keep your existing automation.'; ?>
<p><a class="o-btn" href="/manage/whatsapp/">← WhatsApp inbox</a></p><form class="o-form" method="post"><?= csrf() ?><section class="o-card"><h2>Inbox connection</h2><p>Add your Meta phone number ID and inbox sync token. Existing n8n automation can stay active. Secrets are write-only; leave them blank to keep saved values.</p><div class="o-grid-form"><label class="o-field"><span>Meta phone number ID</span><input name="wa_phone_number_id" value="<?= e($integration['wa_phone_number_id']) ?>" inputmode="numeric"></label><label class="o-field"><span>Inbox sync token</span><input name="wa_sync_token" type="password" autocomplete="new-password"><small>Use the same bearer token in your n8n inbox sync request.</small></label></div></section><section class="o-card"><details><summary>Staff reply provider and advanced connection settings</summary><label class="o-field"><span>Message provider</span><select name="wa_provider"><?php foreach(['console'=>'Local testing only','meta_cloud'=>'Meta Cloud API','n8n'=>'n8n automation'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $integration['wa_provider']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><div class="o-grid-form"><?php foreach(['wa_waba_id'=>'WhatsApp Business Account ID','n8n_send_url'=>'n8n send URL','n8n_receive_url'=>'n8n incoming forwarding URL'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" value="<?= e($integration[$key]) ?>"></label><?php endforeach; ?><?php foreach(['wa_token'=>'Meta access token','wa_app_secret'=>'Meta app secret','wa_verify_token'=>'Meta verification token','n8n_auth_token'=>'n8n bearer token'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" type="password" autocomplete="new-password"></label><?php endforeach; ?></div></details></section><button class="o-btn o-btn-primary">Save connection</button></form><section class="o-card"><h2>Automation endpoints</h2><p>Meta callback: <code><?= e(rtrim(getenv('APP_URL'),'/').'/webhooks/whatsapp/') ?></code></p><p>n8n inbox sync: <code><?= e(rtrim(getenv('APP_URL'),'/').'/webhooks/whatsapp/n8n/') ?></code></p><p>Use Create order in a conversation to enter a booking. Staff sending requires a configured sender and hosting cron; existing automation remains separate.</p></section>
